function mostFrequent(nums) {
  const a = [...nums].sort((p, q) => p - q);
  let best = a[0], bestc = 0;
  for (let i = 0; i < a.length; ) { let j = i; while (j < a.length && a[j] === a[i]) j++; if (j - i > bestc) { bestc = j - i; best = a[i]; } i = j; }
  return best;
}
